		{`[{"name":"m","timestamp":2,"value":1}]`, `[{"name":"m","timestamp":3,"value":-1e16}]`, `[{"name":"m","timestamp":1,"value":1e16}]`},
		{`[{"name":"m","timestamp":1,"value":-1e16},{"name":"m","timestamp":2,"value":1},{"name":"m","timestamp":3,"value":1e16}]`},
