type failAfterReader struct {
	data []byte
	n    int
	err  error
}

func (r *failAfterReader) Read(p []byte) (int, error) {
	if r.n >= len(r.data) {
		return 0, r.err
	}
	c := copy(p, r.data[r.n:])
	r.n += c
	if r.n >= len(r.data) {
		return c, r.err
	}
	return c, nil
}

