		`{"name":"m","timestamp":20,"value":800,"labels":{"aa":"x"}}`,                       // 8,800 -> 404
		`{"name":"m","timestamp":20,"value":900,"labels":{"b":"x"}}`,                        // 9,900 -> 454.5
		`{"name":"m","timestamp":20,"value":1000,"labels":{"k":"\"q\""}}`,                   // 10,1000 -> 505
		`{"name":"m","timestamp":20,"value":1100,"labels":{"k":"\\s"}}`,                     // 11,1100 -> 555.5
		`{"name":"m","timestamp":20,"value":1200,"labels":{"k":"中","z":"a,b=c\\d\"e中"}}`, // 12,1200 -> 606
		`{"name":"mz","timestamp":20,"value":1300}`,                                         // 13,1300 -> 656.5
		`{"name":"m中","timestamp":20,"value":1400}`,                                        // 14,1400 -> 707
		`{"name":"指标","timestamp":20,"value":1500,"labels":{"a":"10","b":"2"}}`,           // 15,1500 -> 757.5
		`{"name":"m2","timestamp":20,"value":1600}`,                                         // 16,1600 -> 808
