		if s.Name != "m" || !reflect.DeepEqual(s.Labels, want[i].labels) {
			t.Fatalf("m series[%d] identity = %v, want %v", i, s, want[i])
		}
		if s.Count != 2 {
			t.Fatalf("m series %v count = %d, want 2", s.Labels, s.Count)
		}
