// reverseWireStrings 返回反序切片，便于以相反提交顺序写同一批点。
func reverseWireStrings(in []string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		out[len(in)-1-i] = s
	}
	return out
}

// mustMarshalResult 把解码后的结果 map 重新按线上编码（SetEscapeHTML(false)）序列化，
// 用于比较两次运行的同一逻辑结果是否逐字节一致。
func mustMarshalResult(t *testing.T, m map[string]interface{}) string {
	t.Helper()
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(m); err != nil {
		t.Fatalf("re-encode result: %v", err)
	}
	return strings.TrimRight(b.String(), "\n")
}

